            __u32 key = 0;
            bpf_map_update_elem(&tcp_options_freq_map, &key, 1, BPF_ADD);
        } else if (opt_kind == 3) {
            __u32 key = 1;
            bpf_map_update_elem(&tcp_options_freq_map, &key, 1, BPF_ADD);
        } else if (opt_kind == 4) {
            __u32 key = 2;
            bpf_map_update_elem(&tcp_options_freq_map, &key, 1, BPF_ADD);
        } else if (opt_kind == 8) {
            __u32 key = 3;
            bpf_map_update_elem(&tcp_options_freq_map, &key, 1, BPF_ADD);
        }

next_opt:
        opt += opt_len;
        options_len -= opt_len;
    }

    return XDP_PASS;
}

